const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const settings={harvest:['厨房收取','收取伙伴','看得见的去向','伙伴轻轻弹起，沿弧线进入仓库；每只到达时，计数与篮子同时回应。','约 0.9 秒','准备好，试着收取这三只鸡宝。'],discovery:['新伙伴','发现伙伴','给第一次，一次亮相','纸面先落定，伙伴再出现，最后落下收录章。庆祝只用在首次发现，重复收取走日常反馈。','约 1.2 秒','点一下，看看首次发现的亮相。'],reward:['营业结算','收下收入','让收入落进口袋','账单盖章，几枚金币飞向右上角；到账时金额递增，钱包轻轻回应。','约 1.0 秒','演示收入 240 CP，重播会重置金额。'],dialog:['弹窗反馈','准备开火','按下去，有回应','木牌轻压，纸面从下方进入；关闭更轻、更快。确认后直接反馈，不等整段动画播完。','入场 220 毫秒','试着打开弹窗，再确认或关闭。']};
let scene='harvest',level='daily',generation=0;
const media=matchMedia('(prefers-reduced-motion: reduce)');
const reduced=()=>media.matches||level==='off';
const speed=()=>$('#slow').checked?2:1;
const animations=new Set(), timers=new Set();
function animate(el,frames,ms,delay=0){if(reduced()){const last=frames.at(-1);for(const [k,v] of Object.entries(last))if(!['offset','easing'].includes(k))el.style[k]=v;return Promise.resolve();}const a=el.animate(frames,{duration:ms*speed(),delay:delay*speed(),easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'});animations.add(a);return a.finished.catch(()=>{}).then(()=>{animations.delete(a);});}
function later(fn,ms){const g=generation;const t=setTimeout(()=>{timers.delete(t);if(g===generation)fn();},reduced()?0:ms*speed());timers.add(t);}
function reset(){generation++;for(const a of animations)a.cancel();animations.clear();for(const t of timers)clearTimeout(t);timers.clear();$$('.stage *, .wallet').forEach(el=>{el.getAnimations().forEach(a=>a.cancel());el.removeAttribute('style');});$('.particles').replaceChildren();$('.modal').hidden=true;$('#balance').textContent='1,280';$('#stock-count').textContent='0 / 3';$('.dialog-hint').textContent='木牌按下 → 纸面出现 → 确认盖章';$('.dialog-hint').classList.remove('confirmed');$('#status').textContent=settings[scene][5];$('#play').textContent=settings[scene][1];document.body.classList.toggle('quiet',reduced());}
function burst(x,y){if(reduced())return;const n=level==='celebrate'?16:5;for(let i=0;i<n;i++){const p=document.createElement('i');p.className='particle';p.style.left=x+'px';p.style.top=y+'px';p.style.background=['#e4b14d','#789451','#d68861'][i%3];$('.particles').append(p);const a=i/n*Math.PI*2,r=level==='celebrate'?75:38;animate(p,[{transform:'translate(0,0) scale(.3)',opacity:0},{opacity:1,offset:.18},{transform:`translate(${Math.cos(a)*r}px,${Math.sin(a)*r-15}px) rotate(${i*40}deg) scale(.4)`,opacity:0}],650).then(()=>p.remove());}}
function pop(el){animate(el,[{transform:'scale(1)'},{transform:'scale(1.07)',offset:.42},{transform:'scale(1)'}],230);}
function local(el){const r=el.getBoundingClientRect(),s=$('#stage').getBoundingClientRect();return {x:r.left-s.left,y:r.top-s.top,w:r.width,h:r.height};}
function fly(src,from,to,size,delay,onArrival){const f=document.createElement('img');f.className='fly';f.src=src;f.alt='';Object.assign(f.style,{left:from.x+'px',top:from.y+'px',width:size+'px',height:size+'px'});$('.particles').append(f);const dx=to.x-from.x,dy=to.y-from.y;const g=generation;animate(f,[{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.45}px,${dy*.35-45}px) scale(.85)`,opacity:1,offset:.48},{transform:`translate(${dx}px,${dy}px) scale(.3)`,opacity:0}],620,delay).then(()=>{f.remove();if(g===generation)onArrival();});}
function play(){reset();if(scene==='harvest'){const target=local($('.stock img'));let count=0;$$('.birds img').forEach((bird,i)=>{later(()=>{const r=local(bird);bird.style.opacity='0';if(reduced()){count++;$('#stock-count').textContent=count+' / 3';$('#status').textContent='3 位伙伴已入仓。';return;}fly(bird.src,r,{x:target.x+10,y:target.y+4},r.w,0,()=>{count++;$('#stock-count').textContent=count+' / 3';pop($('.stock img'));if(count===3){burst(target.x+30,target.y+20);$('#status').textContent='3 位伙伴已入仓。';}});},i*90);});}
else if(scene==='discovery'){animate($('.discovery-paper'),[{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],230);animate($('.new-bird'),[{transform:'translateY(16px) scale(.82)',opacity:0},{transform:'translateY(-5px) scale(1.045)',opacity:1,offset:.65},{transform:'translateY(0) scale(1)',opacity:1}],500,130);animate($('.discovery-stamp'),[{transform:'scale(1.55) rotate(-15deg)',opacity:0},{transform:'scale(.95) rotate(-6deg)',opacity:1,offset:.72},{transform:'scale(1) rotate(-6deg)',opacity:1}],280,600);later(()=>burst($('#stage').clientWidth/2,160),300);later(()=>{$('#status').textContent='新伙伴已收录，继续玩不需要等待。';},900);}
else if(scene==='reward'){animate($('.receipt-stamp'),[{transform:'scale(1.5) rotate(-12deg)',opacity:0},{transform:'scale(1) rotate(-5deg)',opacity:1}],260);if(reduced()){$('#balance').textContent='1,520';$('#status').textContent='营业收入 +240 CP，已到账。';return;}const r=local($('.coin-pile')),wallet=local($('.wallet')),target={x:wallet.x+12,y:wallet.y+7};const n=level==='celebrate'?9:5;for(let i=0;i<n;i++)later(()=>fly($('.coin-pile').src,r,target,32,0,()=>{const amount=1280+Math.round(240*(i+1)/n);$('#balance').textContent=amount.toLocaleString('en-US');pop($('.wallet'));if(i===n-1)$('#status').textContent='营业收入 +240 CP，已到账。';}),200+i*40);}
else{$('.modal').hidden=false;animate($('.paper-dialog'),[{opacity:0,transform:'translateY(16px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],220);$('#confirm').focus({preventScroll:true});}$('#play').textContent=scene==='dialog'?'重新打开':'再看一次';}
async function dismiss(confirm=false){const g=generation;const panel=$('.paper-dialog');if(confirm){$('.dialog-hint').textContent='✓ 已开火';$('.dialog-hint').classList.add('confirmed');$('#status').textContent='已开火，确认即时生效。';}else $('#status').textContent='已关闭，可以继续操作。';await animate(panel,[{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(6px)'}],140);if(g!==generation)return;$('.modal').hidden=true;if(confirm){burst($('#stage').clientWidth/2,175);pop($('.host-bird'));}$('#play').focus({preventScroll:true});}
$('#play').onclick=play;$('#confirm').onclick=()=>dismiss(true);$('#dismiss').onclick=()=>dismiss();$('.modal').onclick=e=>{if(e.target===$('.modal'))dismiss();};document.addEventListener('keydown',e=>{if($('.modal').hidden)return;if(e.key==='Escape')dismiss();if(e.key==='Tab'){const a=$('#confirm'),b=$('#dismiss');if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}});
$$('[data-demo]').forEach(button=>button.onclick=()=>{scene=button.dataset.demo;$$('[data-demo]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$$('[data-scene]').forEach(el=>el.hidden=el.dataset.scene!==scene);const s=settings[scene];$('.scene-title').textContent=s[0];$('#effect-title').textContent=s[2];$('#effect-copy').textContent=s[3];$('#duration').textContent=s[4];reset();});
function updateMotion(){reset();$('#motion-note').textContent=media.matches?'系统已开启减少动态效果：保留结果反馈，关闭位移与粒子。':level==='off'?'关闭：状态即时变化，方便与动效版本对比。':level==='daily'?'日常：短位移、少量纸星，不打断连续操作。':'庆祝：增加纸星与金币，适合首次发现和大奖励。';}
$$('[data-level]').forEach(button=>button.onclick=()=>{level=button.dataset.level;$$('[data-level]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));updateMotion();});$('#slow').onchange=reset;media.addEventListener('change',updateMotion);updateMotion();
